import React, { useEffect, useMemo, useRef, useState } from "react";
import { AccessibilityInfo, View, type ViewStyle } from "react-native";
import { Gesture, GestureDetector, GestureHandlerRootView } from "react-native-gesture-handler";
import {
  BlurStyle,
  Canvas,
  Group,
  PaintStyle,
  Picture,
  Skia,
  StrokeCap,
  StrokeJoin,
  TileMode,
  vec,
  type SkCanvas,
  type SkPicture,
} from "@shopify/react-native-skia";
import {
  DEFAULT_SPEED,
  MAX_SPEED,
  MIN_SPEED,
  advance,
  colorOf,
  createWorld,
  launch,
  simulateToRest,
  type PocketColor,
  type RouletteWorld,
} from "./rouletteMath";
import { WHEEL_H, WHEEL_W, buildFrame, staticScene, type Item } from "./rouletteDesign";

export type RouletteEvent = "launch" | "drop" | "deflector" | "fret" | "settle";

export type RouletteWheelProps = {
  /** Width in layout points; the wheel keeps its 340 x 336 proportions. */
  width?: number;
  slowMotion?: boolean;
  reducedMotion?: boolean;
  /** Increment to spin the wheel and launch the ball for the user. */
  spinTick?: number;
  /** Called once the ball has settled in a pocket. */
  onSettled?: (result: { number: number; color: PocketColor }) => void;
  /** Called as soon as a ball is launched. */
  onLaunch?: () => void;
  /** Hook haptics here: 'launch', 'drop' (ball leaves the track), 'deflector' and 'fret' hits (strength 0 to 1) and 'settle'. */
  onFeedback?: (event: RouletteEvent, strength?: number) => void;
  label?: string;
  style?: ViewStyle;
};

function safeDispose(o: unknown): void {
  const d = (o as { dispose?: () => void } | null | undefined)?.dispose;
  if (typeof d === "function") {
    try {
      d.call(o);
    } catch {
      /* some hosts free these on their own */
    }
  }
}

/** Paint a draw list with Skia. */
function paintItems(canvas: SkCanvas, items: Item[]) {
  const paint = Skia.Paint();
  paint.setAntiAlias(true);
  const blurs = new Map<number, ReturnType<typeof Skia.MaskFilter.MakeBlur>>();
  for (const it of items) {
    paint.setShader(null);
    paint.setMaskFilter(null);
    paint.setStyle(PaintStyle.Fill);
    paint.setColor(Skia.Color(it.color));
    let shader: ReturnType<typeof Skia.Shader.MakeLinearGradient> | null = null;
    if (it.rgrad) {
      shader = Skia.Shader.MakeRadialGradient(
        vec(it.rgrad.cx, it.rgrad.cy),
        it.rgrad.r,
        [Skia.Color(it.rgrad.c0), Skia.Color(it.rgrad.c1)],
        null,
        TileMode.Clamp,
      );
      paint.setShader(shader);
    } else if (it.k === "poly" && it.grad) {
      shader = Skia.Shader.MakeLinearGradient(
        vec(it.grad.x0, it.grad.y0),
        vec(it.grad.x1, it.grad.y1),
        [Skia.Color(it.grad.c0), Skia.Color(it.grad.c1)],
        null,
        TileMode.Clamp,
      );
      paint.setShader(shader);
    }
    if (it.blur) {
      const key = Math.round(it.blur * 10);
      let f = blurs.get(key);
      if (!f) {
        f = Skia.MaskFilter.MakeBlur(BlurStyle.Normal, it.blur / 2, true);
        blurs.set(key, f);
      }
      paint.setMaskFilter(f);
    }
    paint.setAlphaf(it.alpha ?? 1);
    if (it.k === "circ") {
      canvas.drawCircle(it.x, it.y, it.r, paint);
    } else {
      const path = Skia.Path.Make();
      path.moveTo(it.pts[0], it.pts[1]);
      for (let i = 2; i < it.pts.length; i += 2) path.lineTo(it.pts[i], it.pts[i + 1]);
      if (it.stroke === undefined || it.closed !== false) path.close();
      if (it.stroke !== undefined) {
        paint.setStyle(PaintStyle.Stroke);
        paint.setStrokeWidth(it.stroke);
        paint.setStrokeCap(StrokeCap.Round);
        paint.setStrokeJoin(StrokeJoin.Round);
      }
      canvas.drawPath(path, paint);
      path.dispose?.();
    }
    paint.setShader(null);
    safeDispose(shader);
  }
  blurs.forEach((f) => safeDispose(f));
  safeDispose(paint);
}

function record(items: Item[]): SkPicture {
  const rec = Skia.PictureRecorder();
  const canvas = rec.beginRecording(Skia.XYWHRect(-WHEEL_W, -WHEEL_H, WHEEL_W * 3, WHEEL_H * 3));
  paintItems(canvas, items);
  return rec.finishRecordingAsPicture();
}

export function RouletteWheel({
  width = WHEEL_W,
  slowMotion = false,
  reducedMotion,
  spinTick = 0,
  onSettled,
  onLaunch,
  onFeedback,
  label = "A roulette wheel. Tap to spin it and launch the ball, or press and drag to set how hard the ball is launched. The ball circles the track, drops through the deflectors, bounces between the pockets and settles in one",
  style,
}: RouletteWheelProps) {
  const scale = width / WHEEL_W;
  const height = WHEEL_H * scale;
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const worldRef = useRef<RouletteWorld | null>(null);
  if (!worldRef.current) worldRef.current = createWorld(11);
  const latest = useRef({ slowMotion, reduce, onSettled, onLaunch, onFeedback });
  latest.current = { slowMotion, reduce, onSettled, onLaunch, onFeedback };
  const statics = useMemo(() => staticScene(), []);
  const [still, setStill] = useState<{ back: SkPicture; front: SkPicture } | null>(null);
  const [frame, setFrame] = useState<{ dyn: SkPicture; overlay: SkPicture } | null>(null);
  const hand = useRef({ charging: false, power: 0 });
  const seq = useRef(1);
  const playing = useRef(false);
  const spinSeen = useRef(spinTick);
  const pendingLaunch = useRef<number | null>(null);

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => {
        if (alive) setSystemReduce(v);
      })
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);

  // The bowl, track and rim never change: record them once.
  useEffect(() => {
    const back = record(statics.back);
    const front = record(statics.front);
    setStill({ back, front });
    return () => {
      setTimeout(() => {
        safeDispose(back);
        safeDispose(front);
      }, 1500);
    };
  }, [statics]);

  useEffect(() => {
    if (spinTick !== spinSeen.current) {
      spinSeen.current = spinTick;
      if (!playing.current) pendingLaunch.current = DEFAULT_SPEED;
    }
  }, [spinTick]);

  // JS-thread frame loop: step the physics, then record the turning wheel and the ball as one picture.
  useEffect(() => {
    let alive = true;
    let last = 0;
    let prev: { dyn: SkPicture; overlay: SkPicture } | null = null;
    const retired: unknown[] = [];
    const loop = (now: number) => {
      if (!alive) return;
      const w = worldRef.current!;
      const dt = last ? Math.min(0.1, (now - last) / 1000) : 1 / 60;
      last = now;
      if (pendingLaunch.current !== null) {
        const speed = pendingLaunch.current;
        pendingLaunch.current = null;
        seq.current += 1;
        launch(w, speed, seq.current * 7919);
        playing.current = true;
        latest.current.onLaunch?.();
        if (latest.current.reduce) simulateToRest(w);
      }
      if (!latest.current.reduce) advance(w, dt * (latest.current.slowMotion ? 0.25 : 1));
      if (w.events.length) {
        const strength = Math.max(0.2, w.impact);
        for (const e of w.events) latest.current.onFeedback?.(e, e === "deflector" || e === "fret" ? strength : 0.6);
        w.events.length = 0;
        w.impact = 0;
      }
      if (playing.current && w.ball.locked && w.result !== null) {
        playing.current = false;
        latest.current.onSettled?.({ number: w.result, color: colorOf(w.result) });
      }
      const f = buildFrame(w, { power: hand.current.power, charging: hand.current.charging });
      const pic = { dyn: record(f.dyn), overlay: record(f.overlay) };
      setFrame(pic);
      if (prev) retired.push(prev.dyn, prev.overlay);
      while (retired.length > 8) safeDispose(retired.shift());
      prev = pic;
      requestAnimationFrame(loop);
    };
    const raf = requestAnimationFrame(loop);
    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      const rest = [...retired, prev?.dyn, prev?.overlay];
      setTimeout(() => rest.forEach(safeDispose), 1500);
    };
  }, []);

  // Press and drag away from where you touched to set the launch power; a plain tap launches at a middling speed.
  const pan = useMemo(
    () =>
      Gesture.Pan()
        .runOnJS(true)
        .minDistance(0)
        .onBegin(() => {
          if (playing.current || pendingLaunch.current !== null) return;
          hand.current = { charging: true, power: 0 };
        })
        .onUpdate((e) => {
          if (!hand.current.charging) return;
          const d = Math.hypot(e.translationX, e.translationY) / scale;
          hand.current.power = d < 10 ? 0 : Math.min(1, (d - 10) / 110);
        })
        .onFinalize(() => {
          const h = hand.current;
          if (!h.charging) return;
          h.charging = false;
          const p = h.power;
          h.power = 0;
          pendingLaunch.current = p > 0 ? MIN_SPEED + (MAX_SPEED - MIN_SPEED) * p : DEFAULT_SPEED;
        }),
    [scale],
  );

  return (
    <GestureHandlerRootView style={{ width, height }}>
      <GestureDetector gesture={pan}>
        <View
          style={[{ width, height, borderRadius: 18, overflow: "hidden", backgroundColor: "#17110d" }, style]}
          accessibilityLabel={label}
          accessibilityRole="image"
          accessibilityActions={[{ name: "activate", label: "Spin the wheel" }]}
          onAccessibilityAction={() => {
            if (!playing.current && pendingLaunch.current === null) pendingLaunch.current = DEFAULT_SPEED;
          }}
          accessible
        >
          <Canvas pointerEvents="none" style={{ width, height }}>
            <Group transform={[{ scale }]}>
              {still ? <Picture picture={still.back} /> : null}
              {frame ? <Picture picture={frame.dyn} /> : null}
              {still ? <Picture picture={still.front} /> : null}
              {frame ? <Picture picture={frame.overlay} /> : null}
            </Group>
          </Canvas>
        </View>
      </GestureDetector>
    </GestureHandlerRootView>
  );
}

/* Roulette wheel physics. Pure TypeScript, no React, so the Skia component, the web
   preview and the tests all run the same simulation.

   Plane: x to the right, y towards the viewer (angles grow clockwise seen from above).
   Units: the wheel bowl has radius 1.

   The ball is a point mass rolling on a height profile H(r), so the pull towards the
   middle is -g H'(r) and a circular orbit appears by itself when v^2 / r = g H'(r). The
   wheel is a rotating frame with its own friction. Between the two sit:
   - the ball track, a curved wall, so a faster ball climbs and a slowing ball spirals in,
   - a shelf with eight fixed diamond deflectors that the ball hits as it drops,
   - the rotor cone that drags the ball towards the wheel's own velocity,
   - 37 pockets split by thin frets that turn with the wheel, with hops in the third
     dimension (height z) so a ball can leap a fret or settle after a few bounces. */

export const POCKETS = 37;
export const DELTA = (Math.PI * 2) / POCKETS;
/** European single-zero order, clockwise. */
export const ORDER = [0, 32, 15, 19, 4, 21, 2, 25, 17, 34, 6, 27, 13, 36, 11, 30, 8, 23, 10, 5, 24, 16, 33, 1, 20, 14, 31, 9, 22, 18, 29, 7, 28, 12, 35, 3, 26];
const RED = new Set([1, 3, 5, 7, 9, 12, 14, 16, 18, 19, 21, 23, 25, 27, 30, 32, 34, 36]);
export type PocketColor = "red" | "black" | "green";
export const colorOf = (n: number): PocketColor => (n === 0 ? "green" : RED.has(n) ? "red" : "black");

/* ---------- geometry ---------- */
export const BALL_R = 0.024;
export const WALL_R = 0.985;
export const TRACK_IN = 0.7;
export const SHELF_IN = 0.6;
export const POCKET_OUT = 0.475;
export const POCKET_IN = 0.315;
export const FRET_H = 0.02;
export const FRET_T = 0.004;
export const DEFLECTOR_COUNT = 8;
export const DEFLECTOR_R = 0.645;
export const DEFLECTOR_H = 0.045;
const DEFL_RADIAL = 0.056;
const DEFL_TANG = 0.034;

const G = 24.5;
const G_Z = 17;
const STEP = 1 / 480;

const smooth = (a: number, b: number, x: number) => {
  const t = Math.max(0, Math.min(1, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
};

/** dH/dr: how steeply the surface rises going outwards. */
export function slope(r: number): number {
  if (r >= TRACK_IN) {
    const s = Math.min(1, (r - TRACK_IN) / 0.28);
    return 0.18 + 2.4 * s * s + (r > 0.98 ? (r - 0.98) * 40 : 0);
  }
  if (r >= 0.58) return 0.18 + 0.12 * smooth(0.64, 0.58, r);
  if (r >= 0.37) return 0.3;
  return 0.3 - 2.7 * smooth(0.37, 0.32, r);
}

const H_STEP = 0.005;
const H_TAB: number[] = (() => {
  const n = Math.round(1.1 / H_STEP) + 1;
  const h = new Array<number>(n).fill(0);
  for (let i = 1; i < n; i++) h[i] = h[i - 1] + 0.5 * (slope((i - 1) * H_STEP) + slope(i * H_STEP)) * H_STEP;
  const min = Math.min(...h);
  return h.map((v) => v - min);
})();
/** Surface height at radius r (lowest point of the pocket floor is 0). */
export function height(r: number): number {
  const f = Math.max(0, Math.min(H_TAB.length - 1.001, r / H_STEP));
  const i = Math.floor(f);
  return H_TAB[i] + (H_TAB[i + 1] - H_TAB[i]) * (f - i);
}

/* ---------- state ---------- */
export type Phase = "idle" | "track" | "shelf" | "rotor" | "pocket" | "settled";
export type Ball = {
  x: number; y: number; vx: number; vy: number; z: number; vz: number;
  live: boolean; locked: boolean; lockRel: number; lockR: number; settleT: number;
};
export type RouletteWorld = {
  t: number;
  theta: number;
  omega: number;
  ball: Ball;
  phase: Phase;
  result: number | null;
  rng: number;
  /** Peak impact strength (0 to 1) since last read, reset by the caller. */
  impact: number;
  /** Events since last read, for haptics. */
  events: ("launch" | "drop" | "deflector" | "fret" | "settle")[];
  hits: number;
  trail: number[];
};

export function mulberry(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function rand(w: RouletteWorld): number {
  w.rng = (w.rng + 0x6d2b79f5) >>> 0;
  let t = w.rng;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}

export function createWorld(seed = 7): RouletteWorld {
  return {
    t: 0, theta: 0.4, omega: -0.35,
    ball: { x: 0, y: 0, vx: 0, vy: 0, z: 0, vz: 0, live: false, locked: false, lockRel: 0, lockR: 0.36, settleT: 0 },
    phase: "idle", result: null, rng: seed, impact: 0, events: [], hits: 0, trail: [],
  };
}

export const MIN_SPEED = 4.8;
export const MAX_SPEED = 8;
export const DEFAULT_SPEED = 6.4;

/** Spin the wheel and send the ball clockwise round the track. speed is the ball's rim speed in bowl radii per second. */
export function launch(w: RouletteWorld, speed = DEFAULT_SPEED, seed?: number): void {
  if (seed !== undefined) w.rng = seed >>> 0;
  const v = Math.max(MIN_SPEED, Math.min(MAX_SPEED, speed));
  w.omega = -(4.0 + rand(w) * 0.7);
  const phi = -2.3 + rand(w) * 0.5;
  const r = 0.955;
  const b = w.ball;
  b.x = r * Math.cos(phi); b.y = r * Math.sin(phi);
  b.vx = -Math.sin(phi) * v; b.vy = Math.cos(phi) * v;
  b.z = 0; b.vz = 0;
  b.live = true; b.locked = false; b.settleT = 0;
  w.phase = "track"; w.result = null; w.hits = 0; w.trail = [];
  w.events.push("launch");
}

export function pocketAt(theta: number, phi: number): number {
  let rel = (phi - theta) % (Math.PI * 2);
  if (rel < 0) rel += Math.PI * 2;
  return Math.min(POCKETS - 1, Math.floor(rel / DELTA));
}
export const numberAt = (idx: number) => ORDER[((idx % POCKETS) + POCKETS) % POCKETS];

export function deflectorPolys(): number[][][] {
  const out: number[][][] = [];
  for (let k = 0; k < DEFLECTOR_COUNT; k++) {
    const a = (k + 0.5) * ((Math.PI * 2) / DEFLECTOR_COUNT);
    const ca = Math.cos(a), sa = Math.sin(a);
    const pts: number[][] = [];
    for (const [dr, dt] of [[DEFL_RADIAL, 0], [0, DEFL_TANG], [-DEFL_RADIAL, 0], [0, -DEFL_TANG]]) {
      const rr = DEFLECTOR_R + dr;
      pts.push([rr * ca - dt * sa, rr * sa + dt * ca]);
    }
    out.push(pts);
  }
  return out;
}
const DEFLECTORS = deflectorPolys();

function closestOnSegment(px: number, py: number, ax: number, ay: number, bx: number, by: number): [number, number] {
  const dx = bx - ax, dy = by - ay;
  const l2 = dx * dx + dy * dy || 1;
  const t = Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / l2));
  return [ax + dx * t, ay + dy * t];
}

/** Bounce the ball off a point obstacle moving with velocity (ux, uy). */
function bounce(w: RouletteWorld, qx: number, qy: number, ux: number, uy: number, rad: number, e: number, kind: "deflector" | "fret"): boolean {
  const b = w.ball;
  let nx = b.x - qx, ny = b.y - qy;
  const d = Math.hypot(nx, ny);
  if (d >= rad || d < 1e-9) return false;
  nx /= d; ny /= d;
  b.x = qx + nx * rad; b.y = qy + ny * rad;
  const rvx = b.vx - ux, rvy = b.vy - uy;
  const vn = rvx * nx + rvy * ny;
  if (vn >= 0) return true;
  b.vx -= (1 + e) * vn * nx;
  b.vy -= (1 + e) * vn * ny;
  // a little friction along the contact, and a hop proportional to how hard it struck
  const tx = -ny, ty = nx;
  const vt = rvx * tx + rvy * ty;
  b.vx -= 0.08 * vt * tx; b.vy -= 0.08 * vt * ty;
  const hit = -vn;
  if (hit > 0.15) {
    const kick = hit * (kind === "deflector" ? 0.55 : 0.4) * (0.55 + 0.9 * rand(w));
    b.vz = Math.max(b.vz, kick);
    w.hits += 1;
    w.impact = Math.max(w.impact, Math.min(1, hit / 5));
    w.events.push(kind);
  }
  return true;
}

/** One fixed physics step. */
export function step(w: RouletteWorld, dt: number): void {
  w.t += dt;
  // The wheel: bearing friction plus viscous drag. It never reverses.
  if (w.omega !== 0) {
    const s = Math.sign(w.omega);
    const mag = Math.abs(w.omega) - (0.06 + 0.07 * Math.abs(w.omega)) * dt;
    w.omega = mag <= 0.002 ? 0 : s * mag;
  }
  w.theta += w.omega * dt;
  const b = w.ball;
  if (!b.live) return;

  if (b.locked) {
    const phi = w.theta + b.lockRel;
    b.x = b.lockR * Math.cos(phi); b.y = b.lockR * Math.sin(phi);
    b.vx = -w.omega * b.y; b.vy = w.omega * b.x;
    return;
  }

  let r = Math.hypot(b.x, b.y) || 1e-9;
  const airborne = b.z > 1e-4 || b.vz > 0;
  const ux = -w.omega * b.y, uy = w.omega * b.x;
  let ax = 0, ay = 0;
  const sp = Math.hypot(b.vx, b.vy);
  if (!airborne) {
    const pull = -G * slope(r);
    ax += (pull * b.x) / r; ay += (pull * b.y) / r;
    // rolling resistance and air drag
    const roll = 0.1 / Math.max(sp, 0.08);
    ax -= b.vx * (0.1 + roll); ay -= b.vy * (0.1 + roll);
    if (r < SHELF_IN) {
      const k = 1.0 * smooth(SHELF_IN, SHELF_IN - 0.05, r);
      ax -= k * (b.vx - ux); ay -= k * (b.vy - uy);
    }
  } else {
    ax -= b.vx * 0.12; ay -= b.vy * 0.12;
    // wheel surface still pulls on the ball in flight through the pocket walls only: none
  }
  b.vx += ax * dt; b.vy += ay * dt;
  b.x += b.vx * dt; b.y += b.vy * dt;

  // vertical hops
  if (airborne) {
    b.vz -= G_Z * dt;
    b.z += b.vz * dt;
    if (b.z <= 0) {
      b.z = 0;
      if (b.vz < -0.12) {
        b.vz = -b.vz * 0.32;
        // landing on the moving rotor grips it a little
        if (r < SHELF_IN) { b.vx += (ux - b.vx) * 0.15; b.vy += (uy - b.vy) * 0.15; }
        w.impact = Math.max(w.impact, Math.min(1, -b.vz / 2));
      } else b.vz = 0;
    }
  }

  r = Math.hypot(b.x, b.y) || 1e-9;
  // outer wall
  if (r > WALL_R) {
    const nx = b.x / r, ny = b.y / r;
    b.x = nx * WALL_R; b.y = ny * WALL_R;
    const vn = b.vx * nx + b.vy * ny;
    if (vn > 0) { b.vx -= 1.25 * vn * nx; b.vy -= 1.25 * vn * ny; }
  }
  // turret base: the ball can never reach the middle
  if (r < POCKET_IN + 0.01) {
    const nx = b.x / r, ny = b.y / r;
    const lim = POCKET_IN + 0.01;
    b.x = nx * lim; b.y = ny * lim;
    const vn = b.vx * nx + b.vy * ny;
    if (vn < 0) { b.vx -= 1.3 * vn * nx; b.vy -= 1.3 * vn * ny; }
    r = lim;
  }

  // deflectors (fixed to the bowl)
  if (r > 0.55 && r < 0.75 && b.z < DEFLECTOR_H) {
    for (const poly of DEFLECTORS) {
      const n = poly.length;
      let bestD = 1e9, qx = 0, qy = 0;
      for (let i = 0; i < n; i++) {
        const p = poly[i], q = poly[(i + 1) % n];
        const [cx, cy] = closestOnSegment(b.x, b.y, p[0], p[1], q[0], q[1]);
        const d = Math.hypot(b.x - cx, b.y - cy);
        if (d < bestD) { bestD = d; qx = cx; qy = cy; }
      }
      if (bestD < BALL_R) { bounce(w, qx, qy, 0, 0, BALL_R, 0.62, "deflector"); break; }
    }
  }

  // frets (turn with the wheel), only when the ball is low enough to meet them
  if (r < POCKET_OUT + 0.03 && r > POCKET_IN - 0.02 && b.z < FRET_H + 0.004) {
    const phi = Math.atan2(b.y, b.x);
    let rel = (phi - w.theta) % (Math.PI * 2);
    if (rel < 0) rel += Math.PI * 2;
    const i0 = Math.floor(rel / DELTA);
    for (let k = -1; k <= 2; k++) {
      const psi = w.theta + (i0 + k) * DELTA;
      const c = Math.cos(psi), s = Math.sin(psi);
      const [qx, qy] = closestOnSegment(b.x, b.y, POCKET_IN * c, POCKET_IN * s, POCKET_OUT * c, POCKET_OUT * s);
      const uqx = -w.omega * qy, uqy = w.omega * qx;
      bounce(w, qx, qy, uqx, uqy, BALL_R + FRET_T, 0.56, "fret");
    }
  }

  // phase and settling
  r = Math.hypot(b.x, b.y);
  const prev = w.phase;
  if (r > TRACK_IN) w.phase = "track";
  else if (r > SHELF_IN) w.phase = "shelf";
  else if (r > POCKET_OUT) w.phase = "rotor";
  else w.phase = "pocket";
  if (prev === "track" && w.phase !== "track") w.events.push("drop");
  if (w.phase === "pocket" && b.z <= 1e-4) {
    const rvx = b.vx - (-w.omega * b.y), rvy = b.vy - w.omega * b.x;
    if (Math.hypot(rvx, rvy) < 0.07) b.settleT += dt; else b.settleT = 0;
    if (b.settleT > 0.4) {
      b.locked = true; b.vz = 0; b.z = 0;
      const phi = Math.atan2(b.y, b.x);
      b.lockRel = phi - w.theta; b.lockR = r;
      w.result = numberAt(pocketAt(w.theta, phi));
      w.phase = "settled";
      w.events.push("settle");
    }
  } else b.settleT = 0;
  if (Math.floor(w.t / 0.03) !== Math.floor((w.t - dt) / 0.03)) {
    w.trail.push(b.x, b.y);
    if (w.trail.length > 24) w.trail.splice(0, 2);
  }
}

/** Advance by dt seconds using fixed sub-steps. */
export function advance(w: RouletteWorld, dt: number): void {
  let left = Math.min(dt, 0.25);
  while (left > 1e-9) {
    const h = Math.min(STEP, left);
    step(w, h);
    left -= h;
  }
}

/** Run until the ball has settled (or maxT seconds pass). Used for Reduce Motion and tests. */
export function simulateToRest(w: RouletteWorld, maxT = 90): void {
  let t = 0;
  while (t < maxT && w.ball.live && !w.ball.locked) {
    step(w, STEP);
    t += STEP;
  }
}

/** The ball's height above the pocket floor, for drawing: surface plus hop. */
export const ballHeight = (w: RouletteWorld): number => height(Math.hypot(w.ball.x, w.ball.y)) + w.ball.z;

/*
  Roulette wheel drawing. Turns the physics world into a flat draw list that the Skia component and the
  Canvas2D web preview both paint, so the two always show the same picture.

  The bowl is real 3D geometry projected with a camera looking down at about 45 degrees: the ball track,
  shelf, rotor cone and pocket ring all use the same height profile the physics rolls on. Every facet is
  lit by one lamp (diffuse plus a glossy lacquer / brass highlight), so the highlight on the track stays
  put while the pockets and frets turn through it. Layers, back to front: still back (table, track, shelf,
  diamonds, rotor, turret), the turning wheel and the ball, still front (the near rim hides what is
  behind it), and the launch-power overlay.
*/
import {
  BALL_R, DEFLECTOR_H, DELTA, FRET_H, ORDER, POCKETS, POCKET_IN, POCKET_OUT, SHELF_IN, TRACK_IN,
  ballHeight, colorOf, deflectorPolys, height, slope, type RouletteWorld,
} from "./rouletteMath";

export const WHEEL_W = 340;
export const WHEEL_H = 336;

export type Grad = { x0: number; y0: number; x1: number; y1: number; c0: string; c1: string };
export type RGrad = { cx: number; cy: number; r: number; c0: string; c1: string };
export type Item =
  | { k: "poly"; pts: number[]; color: string; alpha?: number; grad?: Grad; rgrad?: RGrad; blur?: number; stroke?: number; closed?: boolean }
  | { k: "circ"; x: number; y: number; r: number; color: string; alpha?: number; rgrad?: RGrad; blur?: number };

type V3 = [number, number, number];

/* ---------- camera ---------- */
const EYE: V3 = [0, 3.2, 1.95];
const TARGET: V3 = [0, 0.1, 0.02];
const FOCAL = 494;
const CX = WHEEL_W / 2;
const CY = 142;
const sub = (a: V3, b: V3): V3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const dot = (a: V3, b: V3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: V3, b: V3): V3 => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const norm = (a: V3): V3 => { const l = Math.hypot(a[0], a[1], a[2]) || 1; return [a[0] / l, a[1] / l, a[2] / l]; };
const FWD = norm(sub(TARGET, EYE));
const RIGHT = norm(cross(FWD, [0, 1, 0]));
const UPV = cross(RIGHT, FWD);

function project(p: V3): [number, number, number] {
  const d = sub(p, EYE);
  const z = dot(d, FWD);
  const s = FOCAL / z;
  return [CX + dot(d, RIGHT) * s, CY - dot(d, UPV) * s, z];
}
/** Bowl plane (x, y) at height h to a 3D point. */
const P3 = (x: number, y: number, h: number): V3 => [x, h, y];
const scr = (x: number, y: number, h: number) => project(P3(x, y, h));

/* ---------- light and materials ---------- */
const LIGHT: V3 = norm([-0.55, 0.78, 0.3]);
const clamp255 = (v: number) => Math.max(0, Math.min(255, Math.round(v)));
const rgb = (r: number, g: number, b: number) => `rgb(${clamp255(r)},${clamp255(g)},${clamp255(b)})`;
const rgba = (r: number, g: number, b: number, a: number) => `rgba(${clamp255(r)},${clamp255(g)},${clamp255(b)},${a})`;

type Mat = { base: V3; gloss: number; spec: number; amb: number };
const WALNUT: Mat = { base: [104, 58, 28], gloss: 70, spec: 210, amb: 0.34 };
const LACQUER: Mat = { base: [78, 40, 18], gloss: 120, spec: 250, amb: 0.3 };
const BRASS: Mat = { base: [190, 142, 62], gloss: 46, spec: 150, amb: 0.36 };

function shade(m: Mat, n: V3, p: V3, tint = 1): string {
  const v = norm(sub(EYE, p));
  const h = norm([LIGHT[0] + v[0], LIGHT[1] + v[1], LIGHT[2] + v[2]]);
  const diff = Math.max(0, dot(n, LIGHT));
  const spec = Math.pow(Math.max(0, dot(n, h)), m.gloss) * m.spec;
  const k = (m.amb + 0.95 * diff) * tint;
  return rgb(m.base[0] * k + spec, m.base[1] * k + spec * 0.92, m.base[2] * k + spec * 0.78);
}
const surfNormal = (s: number, phi: number): V3 => norm([-s * Math.cos(phi), 1, -s * Math.sin(phi)]);
const grain = (a: number, r: number) => 0.965 + 0.035 * Math.sin(a * 23 + r * 41) * Math.cos(a * 7 - r * 13) + 0.02 * Math.sin(a * 91 + r * 9);

/* ---------- builders ---------- */
function ring(items: Item[], r0: number, r1: number, n: number, hAt: (r: number) => number, mat: Mat, opts: { bands?: number; cull?: boolean; skew?: number; normalAt?: (r: number, phi: number) => V3; tintAt?: (a: number, r: number) => number } = {}) {
  const bands = opts.bands ?? 4;
  const quads: { depth: number; it: Item }[] = [];
  for (let i = 0; i < n; i++) {
    const a0 = (i / n) * Math.PI * 2, a1 = ((i + 1) / n) * Math.PI * 2, am = (a0 + a1) / 2;
    for (let j = 0; j < bands; j++) {
      const ra = r0 + ((r1 - r0) * j) / bands, rb = r0 + ((r1 - r0) * (j + 1)) / bands, rm = (ra + rb) / 2;
      const s = (hAt(rb) - hAt(ra)) / (rb - ra);
      const nrm = opts.normalAt ? opts.normalAt(rm, am) : surfNormal(s, am);
      const c = P3(rm * Math.cos(am), rm * Math.sin(am), hAt(rm));
      if (opts.cull !== false && dot(nrm, sub(EYE, c)) <= 0) continue;
      const pts: number[] = [];
      for (const [r, a] of [[ra, a0], [rb, a0], [rb, a1], [ra, a1]] as [number, number][]) {
        const q = scr(r * Math.cos(a), r * Math.sin(a), hAt(r));
        pts.push(q[0], q[1]);
      }
      const tint = (opts.tintAt ? opts.tintAt(am, rm) : 1) * grain(am, rm);
      quads.push({ depth: project(c)[2], it: { k: "poly", pts, color: shade(mat, nrm, c, tint) } });
    }
  }
  quads.sort((a, b) => b.depth - a.depth);
  for (const q of quads) items.push(q.it);
}

function wall(items: Item[], r: number, h0: number, h1: number, n: number, mat: Mat, inward: boolean) {
  const quads: { depth: number; it: Item }[] = [];
  for (let i = 0; i < n; i++) {
    const a0 = (i / n) * Math.PI * 2, a1 = ((i + 1) / n) * Math.PI * 2, am = (a0 + a1) / 2;
    const nrm: V3 = inward ? [-Math.cos(am), 0, -Math.sin(am)] : [Math.cos(am), 0, Math.sin(am)];
    const c = P3(r * Math.cos(am), r * Math.sin(am), (h0 + h1) / 2);
    if (dot(nrm, sub(EYE, c)) <= 0) continue;
    const pts: number[] = [];
    for (const [a, h] of [[a0, h1], [a1, h1], [a1, h0], [a0, h0]] as [number, number][]) {
      const q = scr(r * Math.cos(a), r * Math.sin(a), h);
      pts.push(q[0], q[1]);
    }
    quads.push({ depth: project(c)[2], it: { k: "poly", pts, color: shade(mat, nrm, c, grain(am, r)) } });
  }
  quads.sort((a, b) => b.depth - a.depth);
  for (const q of quads) items.push(q.it);
}

function ellipse3D(cx: number, cy: number, h: number, rad: number, n = 14): number[] {
  const pts: number[] = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const q = scr(cx + rad * Math.cos(a), cy + rad * Math.sin(a), h);
    pts.push(q[0], q[1]);
  }
  return pts;
}

/* ---------- geometry of the bowl ---------- */
const RIM_IN = 0.985;
const RIM_OUT = 1.1;
const RIM_Y = height(0.985) + 0.06;
const BASE_Y = -0.06;
const TURRET_BASE = height(POCKET_IN);
const TURRET_TOP = TURRET_BASE + 0.27;
const turretH = (r: number) => (r >= POCKET_IN ? height(r) : TURRET_BASE + ((POCKET_IN - r) / (POCKET_IN - 0.1)) * (TURRET_TOP - TURRET_BASE));
const rotorH = (r: number) => height(r);

export function staticScene(): { back: Item[]; front: Item[] } {
  const back: Item[] = [];
  const front: Item[] = [];

  // table and the shadow the bowl throws on it
  back.push({ k: "poly", pts: [0, 0, WHEEL_W, 0, WHEEL_W, WHEEL_H, 0, WHEEL_H], color: "#17110d", grad: { x0: 0, y0: 0, x1: WHEEL_W, y1: WHEEL_H, c0: "#241a13", c1: "#0d0907" } });
  back.push({ k: "poly", pts: ellipse3D(0.1, 0.14, BASE_Y, 1.3, 40), color: "#000", alpha: 0.6, blur: 22 });
  back.push({ k: "poly", pts: ellipse3D(0, 0, BASE_Y, 1.2, 40), color: "#000", alpha: 0.35, blur: 8 });

  // outer wall of the bowl (near side only) goes in front
  wall(front, RIM_OUT, BASE_Y, RIM_Y, 160, WALNUT, false);
  // base ring of brass at the foot
  wall(front, RIM_OUT + 0.012, BASE_Y, BASE_Y + 0.05, 90, BRASS, false);

  // ball track: a curved wall lit as a lacquered walnut bowl
  ring(back, TRACK_IN, RIM_IN, 200, height, LACQUER, { bands: 8 });
  // brass trim where the track meets the shelf
  ring(back, TRACK_IN - 0.012, TRACK_IN + 0.004, 96, height, BRASS, { bands: 1, cull: false });
  // shelf
  ring(back, SHELF_IN + 0.01, TRACK_IN - 0.012, 144, height, WALNUT, { bands: 3, tintAt: () => 1.0 });

  // deflectors: brass diamonds standing on the shelf
  const polys = deflectorPolys().map((poly) => ({ poly, depth: project(P3(poly[0][0] * 0.5 + poly[2][0] * 0.5, poly[0][1] * 0.5 + poly[2][1] * 0.5, height(0.645)))[2] }));
  polys.sort((a, b) => b.depth - a.depth);
  for (const { poly } of polys) {
    const cxm = (poly[0][0] + poly[2][0]) / 2, cym = (poly[0][1] + poly[2][1]) / 2;
    back.push({ k: "poly", pts: ellipse3D(cxm - 0.04, cym + 0.015, height(0.645), 0.05, 12), color: "#000", alpha: 0.45, blur: 3 });
    const h0 = height(0.645);
    for (let i = 0; i < 4; i++) {
      const p = poly[i], q = poly[(i + 1) % 4];
      const ex = q[0] - p[0], ey = q[1] - p[1];
      const nrm = norm([ey, 0, -ex]); // outward for this winding, flipped below if needed
      const mid = P3((p[0] + q[0]) / 2, (p[1] + q[1]) / 2, h0 + DEFLECTOR_H / 2);
      const outward: V3 = [mid[0] - cxm, 0, mid[2] - cym];
      const nn: V3 = dot(nrm, outward) < 0 ? [-nrm[0], 0, -nrm[2]] : nrm;
      if (dot(nn, sub(EYE, mid)) <= 0) continue;
      const a = scr(p[0], p[1], h0), b = scr(q[0], q[1], h0), c = scr(q[0], q[1], h0 + DEFLECTOR_H), d = scr(p[0], p[1], h0 + DEFLECTOR_H);
      back.push({ k: "poly", pts: [a[0], a[1], b[0], b[1], c[0], c[1], d[0], d[1]], color: shade(BRASS, nn, mid) });
    }
    const top = poly.map((p) => scr(p[0], p[1], h0 + DEFLECTOR_H));
    const tp: number[] = [];
    top.forEach((t) => tp.push(t[0], t[1]));
    back.push({ k: "poly", pts: tp, color: shade(BRASS, [0, 1, 0], P3(cxm, cym, h0 + DEFLECTOR_H)), grad: { x0: tp[0], y0: tp[1], x1: tp[4], y1: tp[5], c0: "#f6dc9c", c1: "#a57a30" } });
  }

  // rotor cone (rotationally plain; the markings that turn are drawn with the wheel)
  ring(back, POCKET_OUT, SHELF_IN + 0.01, 144, rotorH, WALNUT, { bands: 3, tintAt: (a) => 0.95 + 0.1 * Math.sin(a * 2) });
  ring(back, POCKET_OUT - 0.006, POCKET_OUT + 0.01, 96, rotorH, BRASS, { bands: 1, cull: false });
  ring(back, SHELF_IN, SHELF_IN + 0.014, 96, rotorH, BRASS, { bands: 1, cull: false });

  // pocket well floor underlay (dark) so thin gaps between pockets never show the background
  ring(back, POCKET_IN, POCKET_OUT, 72, rotorH, { base: [12, 10, 10], gloss: 10, spec: 0, amb: 1 }, { bands: 1, cull: false });

  // turret: polished brass cone with a lamp highlight
  const tN = 120;
  const tq: { depth: number; it: Item }[] = [];
  for (let i = 0; i < tN; i++) {
    const a0 = (i / tN) * Math.PI * 2, a1 = ((i + 1) / tN) * Math.PI * 2, am = (a0 + a1) / 2;
    for (let j = 0; j < 8; j++) {
      const ra = POCKET_IN - ((POCKET_IN - 0.1) * j) / 8, rb = POCKET_IN - ((POCKET_IN - 0.1) * (j + 1)) / 8;
      const s = (turretH(rb) - turretH(ra)) / (rb - ra);
      const nrm = surfNormal(s, am);
      const rm = (ra + rb) / 2;
      const c = P3(rm * Math.cos(am), rm * Math.sin(am), turretH(rm));
      const pts: number[] = [];
      for (const [r, a] of [[ra, a0], [rb, a0], [rb, a1], [ra, a1]] as [number, number][]) {
        const q = scr(r * Math.cos(a), r * Math.sin(a), turretH(r));
        pts.push(q[0], q[1]);
      }
      tq.push({ depth: project(c)[2], it: { k: "poly", pts, color: shade({ ...BRASS, gloss: 30, spec: 120 }, nrm, c, 1) } });
    }
  }
  tq.sort((a, b) => b.depth - a.depth);
  tq.forEach((q) => back.push(q.it));
  const dome = scr(0, 0, TURRET_TOP);
  back.push({ k: "circ", x: dome[0], y: dome[1], r: 0.105 * FOCAL / dome[2], color: "#e8c878", rgrad: { cx: dome[0] - 3, cy: dome[1] - 3, r: 0.105 * FOCAL / dome[2] * 1.15, c0: "#fff4d0", c1: "#9c7226" } });

  // near rim top (flat lacquered walnut) goes in front of the ball
  ring(front, RIM_IN, RIM_OUT, 120, () => RIM_Y, WALNUT, { bands: 3, normalAt: () => [0, 1, 0], cull: false });
  // chamfer and brass inlay ring on the rim
  ring(front, RIM_IN - 0.006, RIM_IN + 0.02, 120, (r) => RIM_Y - (r < RIM_IN + 0.01 ? 0.02 : 0), BRASS, { bands: 1, normalAt: () => [0, 1, 0], cull: false });
  ring(front, 1.045, 1.055, 120, () => RIM_Y + 0.0005, BRASS, { bands: 1, normalAt: () => [0, 1, 0], cull: false });
  return { back, front };
}

/* ---------- the turning wheel and the ball ---------- */
const PALETTE = {
  red: [168, 22, 28] as V3,
  black: [22, 22, 26] as V3,
  green: [18, 118, 52] as V3,
};

export type FrameOpts = { power?: number; charging?: boolean };

export function buildFrame(w: RouletteWorld, opts: FrameOpts = {}): { dyn: Item[]; overlay: Item[] } {
  const dyn: Item[] = [];
  const overlay: Item[] = [];

  // rotor studs turn with the wheel
  for (let i = 0; i < POCKETS; i++) {
    const a = w.theta + (i + 0.5) * DELTA;
    const r = 0.53;
    const s = scr(r * Math.cos(a), r * Math.sin(a), rotorH(r) + 0.004);
    const nrm = surfNormal(slope(r), a);
    dyn.push({ k: "circ", x: s[0], y: s[1], r: 1.55, color: shade(BRASS, nrm, P3(r * Math.cos(a), r * Math.sin(a), rotorH(r))) });
    dyn.push({ k: "circ", x: s[0] - 0.4, y: s[1] - 0.5, r: 0.5, color: "#fff2c8", alpha: 0.8 });
  }

  // pockets: order by depth so the near frets overlap the far floors correctly
  const pk: { depth: number; items: Item[] }[] = [];
  for (let i = 0; i < POCKETS; i++) {
    const n = ORDER[i];
    const col = PALETTE[colorOf(n)];
    const a0 = w.theta + i * DELTA, a1 = a0 + DELTA, am = (a0 + a1) / 2;
    const rm = (POCKET_IN + POCKET_OUT) / 2;
    const c3 = P3(rm * Math.cos(am), rm * Math.sin(am), rotorH(rm));
    const nrm = surfNormal(slope(rm), am);
    const pts: number[] = [];
    const arcs: [number, number][] = [];
    for (const a of [a0, (a0 + a1) / 2, a1]) arcs.push([POCKET_OUT, a]);
    for (const a of [a1, (a0 + a1) / 2, a0]) arcs.push([POCKET_IN, a]);
    for (const [r, a] of arcs) {
      const q = scr(r * Math.cos(a), r * Math.sin(a), rotorH(r));
      pts.push(q[0], q[1]);
    }
    const lam = 0.38 + 0.95 * Math.max(0, dot(nrm, LIGHT));
    const sheen = Math.pow(Math.max(0, dot(nrm, norm([LIGHT[0] + 0, LIGHT[1] + 0.9, LIGHT[2] + 0.7]))), 30) * 90;
    const base = rgb(col[0] * lam + sheen, col[1] * lam + sheen, col[2] * lam + sheen);
    const lo = scr(POCKET_IN * Math.cos(am), POCKET_IN * Math.sin(am), rotorH(POCKET_IN));
    const hi = scr(POCKET_OUT * Math.cos(am), POCKET_OUT * Math.sin(am), rotorH(POCKET_OUT));
    const items: Item[] = [
      { k: "poly", pts, color: base, grad: { x0: hi[0], y0: hi[1], x1: lo[0], y1: lo[1], c0: rgb(col[0] * lam * 1.15 + sheen, col[1] * lam * 1.15 + sheen, col[2] * lam * 1.15 + sheen), c1: rgb(col[0] * lam * 0.55, col[1] * lam * 0.55, col[2] * lam * 0.55) } },
    ];
    // fret on the leading edge of the pocket: brass ridge, bright on the lit side
    const f0 = scr(POCKET_IN * Math.cos(a0), POCKET_IN * Math.sin(a0), rotorH(POCKET_IN) + FRET_H);
    const f1 = scr(POCKET_OUT * Math.cos(a0), POCKET_OUT * Math.sin(a0), rotorH(POCKET_OUT) + FRET_H);
    const g0 = scr(POCKET_IN * Math.cos(a0), POCKET_IN * Math.sin(a0), rotorH(POCKET_IN));
    const g1 = scr(POCKET_OUT * Math.cos(a0), POCKET_OUT * Math.sin(a0), rotorH(POCKET_OUT));
    const fn: V3 = [-Math.sin(a0), 0.2, Math.cos(a0)];
    const lit = Math.max(0.35, 0.55 + 0.7 * dot(norm(fn), LIGHT));
    items.push({ k: "poly", pts: [g0[0] + 1, g0[1] + 1.5, g1[0] + 1, g1[1] + 1.5], color: "#000", alpha: 0.35, stroke: 1.8, closed: false });
    items.push({ k: "poly", pts: [f0[0], f0[1], f1[0], f1[1]], color: rgb(206 * lit, 156 * lit, 66 * lit), stroke: 1.7, closed: false });
    items.push({ k: "poly", pts: [f0[0], f0[1] - 0.5, f1[0], f1[1] - 0.5], color: rgb(255 * Math.min(1, lit + 0.1), 238 * Math.min(1, lit + 0.1), 190 * Math.min(1, lit + 0.1)), alpha: 0.7, stroke: 0.6, closed: false });
    items.push({ k: "circ", x: f1[0], y: f1[1], r: 1.5, color: rgb(228 * lit, 186 * lit, 96 * lit) });
    pk.push({ depth: project(c3)[2], items });
  }
  pk.sort((a, b) => b.depth - a.depth);
  pk.forEach((p) => dyn.push(...p.items));

  // cross handle on the turret
  for (const k of [0, 1]) {
    const a = w.theta + (k * Math.PI) / 2 + 0.3;
    const e: number[] = [];
    for (const rr of [-0.27, -0.13, 0, 0.13, 0.27]) {
      const r = Math.abs(rr);
      const h = TURRET_TOP + 0.018 - r * 0.55;
      const q = scr(Math.cos(a) * rr, Math.sin(a) * rr, h);
      e.push(q[0], q[1]);
    }
    dyn.push({ k: "poly", pts: e.map((v, i) => (i % 2 ? v + 2.2 : v + 1.2)), color: "#000", alpha: 0.35, stroke: 3.6, closed: false });
    dyn.push({ k: "poly", pts: e, color: "#c99a45", stroke: 3.4, closed: false });
    dyn.push({ k: "poly", pts: e.map((v, i) => (i % 2 ? v - 0.9 : v - 0.3)), color: "#fff0c0", alpha: 0.75, stroke: 1, closed: false });
    for (const sgn of [-1, 1]) {
      const r = 0.27;
      const q = scr(Math.cos(a) * r * sgn, Math.sin(a) * r * sgn, TURRET_TOP + 0.018 - r * 0.55 + 0.012);
      const rad = 0.034 * FOCAL / q[2];
      dyn.push({ k: "circ", x: q[0], y: q[1], r: rad, color: "#d9ac55", rgrad: { cx: q[0] - rad * 0.35, cy: q[1] - rad * 0.4, r: rad * 1.2, c0: "#fff3cf", c1: "#8a6420" } });
    }
  }
  const top = scr(0, 0, TURRET_TOP + 0.06);
  const tr = 0.045 * FOCAL / top[2];
  dyn.push({ k: "circ", x: top[0], y: top[1], r: tr, color: "#e0b45a", rgrad: { cx: top[0] - tr * 0.35, cy: top[1] - tr * 0.4, r: tr * 1.3, c0: "#fffbe6", c1: "#8a6420" } });

  // ball
  const b = w.ball;
  if (b.live) {
    const r = Math.hypot(b.x, b.y) || 1e-9;
    const hs = height(r);
    const s = slope(r);
    const nrm = surfNormal(s, Math.atan2(b.y, b.x));
    const surf = P3(b.x, b.y, hs);
    const cen: V3 = [surf[0] + nrm[0] * BALL_R, surf[1] + nrm[1] * BALL_R + b.z, surf[2] + nrm[2] * BALL_R];
    const pc = project(cen);
    const rad = (BALL_R * 1.25 * FOCAL) / pc[2];
    // streak behind a fast ball
    const speed = Math.hypot(b.vx, b.vy);
    const t = w.trail;
    if (speed > 1.4 && b.z < 0.05) {
      const n = t.length / 2;
      for (let i = Math.max(0, n - 7); i < n - 1; i++) {
        const q0 = scr(t[i * 2], t[i * 2 + 1], height(Math.hypot(t[i * 2], t[i * 2 + 1])) + BALL_R);
        const q1 = scr(t[i * 2 + 2], t[i * 2 + 3], height(Math.hypot(t[i * 2 + 2], t[i * 2 + 3])) + BALL_R);
        const f = (i - (n - 8)) / 7;
        dyn.push({ k: "poly", pts: [q0[0], q0[1], q1[0], q1[1]], color: "#e8edf2", alpha: Math.min(0.16, 0.025 * speed) * Math.max(0, f), stroke: rad * 1.5, closed: false });
      }
    }
    // shadow: cast along the lamp direction, softer and fainter the higher the ball is
    const lift = BALL_R + b.z;
    const sx = b.x - (LIGHT[0] / LIGHT[1]) * lift, sy = b.y - (LIGHT[2] / LIGHT[1]) * lift;
    const sr = Math.hypot(sx, sy) || 1e-9;
    const spin = ellipse3D(sx, sy, height(sr) + 0.001, BALL_R * 1.05, 14);
    dyn.push({ k: "poly", pts: spin, color: "#000", alpha: Math.max(0.2, 0.6 - b.z * 9), blur: 1.5 + b.z * 90 });
    // chrome sphere: dark rim, warm wood reflected low, window highlight high left
    dyn.push({ k: "circ", x: pc[0], y: pc[1], r: rad, color: "#9aa2ab", rgrad: { cx: pc[0] - rad * 0.2, cy: pc[1] - rad * 0.25, r: rad * 1.15, c0: "#e9eef3", c1: "#2c3138" } });
    dyn.push({ k: "circ", x: pc[0] + rad * 0.28, y: pc[1] + rad * 0.5, r: rad * 0.62, color: "#b57a3c", alpha: 0.5, rgrad: { cx: pc[0] + rad * 0.28, cy: pc[1] + rad * 0.5, r: rad * 0.62, c0: "#c98a46", c1: "rgba(120,70,30,0)" } });
    dyn.push({ k: "circ", x: pc[0] - rad * 0.36, y: pc[1] - rad * 0.4, r: rad * 0.3, color: "#ffffff", alpha: 0.95, rgrad: { cx: pc[0] - rad * 0.36, cy: pc[1] - rad * 0.4, r: rad * 0.3, c0: "#ffffff", c1: "rgba(255,255,255,0)" } });
    dyn.push({ k: "circ", x: pc[0] + rad * 0.5, y: pc[1] - rad * 0.1, r: rad * 0.1, color: "#ffffff", alpha: 0.55 });
  }

  // launch power: a row of ticks on the near rim fills as the finger drags
  if (opts.charging) {
    const p = Math.max(0, Math.min(1, opts.power ?? 0));
    const N = 26;
    for (let i = 0; i < N; i++) {
      const a = Math.PI * (0.18 + (0.64 * i) / (N - 1));
      const q0 = scr(1.0 * Math.cos(a), 1.0 * Math.sin(a), RIM_Y + 0.003);
      const q1 = scr(1.085 * Math.cos(a), 1.085 * Math.sin(a), RIM_Y + 0.003);
      const on = i / (N - 1) <= p + 1e-6 && p > 0;
      overlay.push({ k: "poly", pts: [q0[0], q0[1], q1[0], q1[1]], color: on ? (i / N > 0.75 ? "#ff6a3d" : "#ffc247") : "#ffffff", alpha: on ? 1 : 0.22, stroke: 2.2, closed: false });
    }
  }
  return { dyn, overlay };
}
export { TRACK_IN, SHELF_IN };

import React, { useState } from "react";
import { Pressable, Text, View } from "react-native";
import { RouletteWheel, type RouletteEvent } from "./RouletteWheel";

const TONE = { red: "#a8161c", black: "#1d1d20", green: "#12753a" } as const;

export default function Example({ onFeedback }: { onFeedback?: (event: RouletteEvent, strength?: number) => void }) {
  const [slow, setSlow] = useState(false);
  const [reduce, setReduce] = useState(false);
  const [spinTick, setSpinTick] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [result, setResult] = useState<{ number: number; color: "red" | "black" | "green" } | null>(null);
  const chip = (on: boolean) => ({
    paddingVertical: 9, paddingHorizontal: 13, borderRadius: 24, borderWidth: 1,
    backgroundColor: on ? "#315843" : "#eeeade", borderColor: on ? "#315843" : "#c7caba",
  });
  return (
    <View style={{ alignItems: "center", gap: 10, paddingVertical: 14 }}>
      <RouletteWheel
        slowMotion={slow}
        reducedMotion={reduce}
        spinTick={spinTick}
        onLaunch={() => { setPlaying(true); setResult(null); }}
        onSettled={(r) => { setPlaying(false); setResult(r); }}
        onFeedback={onFeedback}
      />
      <Text accessibilityLiveRegion="polite" style={{ fontSize: 15, color: result ? TONE[result.color] : "#1f3a2a", fontFamily: "Geist-Regular", minHeight: 20 }}>
        {playing ? "Ball in play" : result ? `${result.number} ${result.color}` : "Tap to spin · drag to set the launch speed"}
      </Text>
      <View style={{ flexDirection: "row", gap: 8, flexWrap: "wrap", justifyContent: "center" }}>
        <Pressable accessibilityRole="button" accessibilityState={{ disabled: playing }} disabled={playing} onPress={() => setSpinTick((v) => v + 1)} style={chip(false)}>
          <Text style={{ fontSize: 12, color: "#315843", fontFamily: "Geist-Regular" }}>Spin</Text>
        </Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: slow }} onPress={() => setSlow((v) => !v)} style={chip(slow)}>
          <Text style={{ fontSize: 12, color: slow ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Slow motion: {slow ? "on" : "off"}</Text>
        </Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: reduce }} onPress={() => setReduce((v) => !v)} style={chip(reduce)}>
          <Text style={{ fontSize: 12, color: reduce ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Reduce motion: {reduce ? "on" : "off"}</Text>
        </Pressable>
      </View>
    </View>
  );
}
